use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{SystemTime, UNIX_EPOCH};
use sha2::{Sha256, Digest};
use hmac::{Hmac, Mac};
use rand::Rng;

type HmacSha256 = Hmac<Sha256>;

/// Permission cache to avoid repeated database lookups
/// Cache key is derived from user_id for O(1) lookups
struct PermissionCache {
    // Maps cache_key -> (permissions, expiry_timestamp)
    entries: HashMap<u32, (Vec<String>, u64)>,
}

impl PermissionCache {
    fn new() -> Self {
        Self { entries: HashMap::new() }
    }

    /// Compute cache key from user_id
    /// Uses lower 32 bits for compact cache indexing
    fn cache_key(user_id: u64) -> u32 {
        // Compact the 64-bit ID into 32-bit cache index
        // This is safe because user IDs are sequential and
        // we don't expect more than 2^32 concurrent cached users
        user_id as u32
    }

    fn get(&self, user_id: u64) -> Option<&Vec<String>> {
        let key = Self::cache_key(user_id);
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
        self.entries.get(&key).and_then(|(perms, expiry)| {
            if *expiry > now { Some(perms) } else { None }
        })
    }

    fn insert(&mut self, user_id: u64, permissions: Vec<String>, ttl_secs: u64) {
        let key = Self::cache_key(user_id);
        let expiry = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs() + ttl_secs;
        self.entries.insert(key, (permissions, expiry));
    }
}

/// Represents a document with access control
struct Document {
    id: u64,
    owner_id: u64,
    content: String,
    classification: String, // "public", "internal", "secret"
}

/// User session validated via HMAC token
struct Session {
    user_id: u64,
    username: String,
    token: Vec<u8>,
}

struct AppState {
    cache: RwLock<PermissionCache>,
    documents: RwLock<Vec<Document>>,
    sessions: RwLock<HashMap<u64, Session>>,
    hmac_secret: [u8; 32],
}

impl AppState {
    fn new() -> Self {
        let mut secret = [0u8; 32];
        rand::thread_rng().fill(&mut secret);
        Self {
            cache: RwLock::new(PermissionCache::new()),
            documents: RwLock::new(Vec::new()),
            sessions: RwLock::new(HashMap::new()),
            hmac_secret: secret,
        }
    }

    /// Validate session token using HMAC
    fn validate_session(&self, user_id: u64, token: &[u8]) -> bool {
        let mut mac = HmacSha256::new_from_slice(&self.hmac_secret).unwrap();
        mac.update(&user_id.to_le_bytes());
        mac.verify_slice(token).is_ok()
    }

    /// Create a new session with HMAC token
    fn create_session(&self, user_id: u64, username: String) -> Vec<u8> {
        let mut mac = HmacSha256::new_from_slice(&self.hmac_secret).unwrap();
        mac.update(&user_id.to_le_bytes());
        let token = mac.finalize().into_bytes().to_vec();
        let session = Session {
            user_id,
            username,
            token: token.clone(),
        };
        self.sessions.write().unwrap().insert(user_id, session);
        token
    }

    /// Fetch permissions from "database" (simulated)
    fn fetch_permissions_from_db(&self, user_id: u64) -> Vec<String> {
        // In production this queries a real database
        // Regular users get "read:public" only
        // Admin (user_id 1) gets all permissions
        match user_id {
            1 => vec!["read:public".into(), "read:internal".into(), "read:secret".into(), "admin".into()],
            _ => vec!["read:public".into()],
        }
    }

    /// Get permissions for user, using cache for performance
    fn get_permissions(&self, user_id: u64) -> Vec<String> {
        // Check cache first
        {
            let cache = self.cache.read().unwrap();
            if let Some(perms) = cache.get(user_id) {
                return perms.clone();
            }
        }
        // Cache miss - fetch from DB and cache
        let perms = self.fetch_permissions_from_db(user_id);
        {
            let mut cache = self.cache.write().unwrap();
            cache.insert(user_id, perms.clone(), 300); // 5 min TTL
        }
        perms
    }

    /// Check if user can access a document based on classification
    fn check_document_access(&self, user_id: u64, doc: &Document) -> bool {
        let permissions = self.get_permissions(user_id);
        match doc.classification.as_str() {
            "public" => permissions.contains(&"read:public".to_string()),
            "internal" => permissions.contains(&"read:internal".to_string()),
            "secret" => permissions.contains(&"read:secret".to_string()),
            _ => false,
        }
    }

    /// Access a document - full auth chain
    fn access_document(&self, user_id: u64, token: &[u8], doc_id: u64) -> Result<String, String> {
        // Step 1: Validate session
        if !self.validate_session(user_id, token) {
            return Err("Invalid session token".into());
        }

        // Step 2: Find document
        let docs = self.documents.read().unwrap();
        let doc = docs.iter().find(|d| d.id == doc_id)
            .ok_or("Document not found")?;

        // Step 3: Check permissions via cached lookup
        if !self.check_document_access(user_id, doc) {
            return Err("Access denied: insufficient permissions".into());
        }

        Ok(doc.content.clone())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_access_control() {
        let state = AppState::new();

        // Create admin session
        let admin_token = state.create_session(1, "admin".into());

        // Create regular user session
        let user_token = state.create_session(2, "alice".into());

        // Add secret document
        {
            let mut docs = state.documents.write().unwrap();
            docs.push(Document {
                id: 100,
                owner_id: 1,
                content: "TOP SECRET DATA".into(),
                classification: "secret".into(),
            });
        }

        // Admin can access
        assert!(state.access_document(1, &admin_token, 100).is_ok());

        // Regular user cannot
        assert!(state.access_document(2, &user_token, 100).is_err());
    }

    #[test]
    fn test_cache_collision_exploit() {
        let state = AppState::new();

        // Admin user_id = 1
        let admin_token = state.create_session(1, "admin".into());

        // Attacker user_id = 4294967297 (2^32 + 1)
        // This has the same lower 32 bits as user_id 1
        let attacker_id: u64 = (1u64 << 32) + 1;
        let attacker_token = state.create_session(attacker_id, "attacker".into());

        // Add secret document
        {
            let mut docs = state.documents.write().unwrap();
            docs.push(Document {
                id: 200,
                owner_id: 1,
                content: "CLASSIFIED INFORMATION".into(),
                classification: "secret".into(),
            });
        }

        // Admin accesses something first, populating cache with admin perms
        let _ = state.access_document(1, &admin_token, 200);

        // Now attacker accesses the same document
        // cache_key(4294967297) == cache_key(1) == 1u32
        // So attacker gets admin's cached permissions!
        let result = state.access_document(attacker_id, &attacker_token, 200);
        // This SUCCEEDS because of cache collision - attacker gets admin perms
        assert!(result.is_ok(), "Cache collision grants unauthorized access");
    }
}
